head.script:
scwin.screenId = "jldfil35706";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    let __pc = $c.util.getComponent('dma_pageContext');
    if (!__pc || !__pc.set || !__pc.get) { return; }
    if (!__pc.get("today")) { __pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function () {
    let __genFills = [{ genId: "c_foreach_77", entity: "dlt_result", countIds: [], cells: [{ childId: "ipt_checkType", fn: function (__v, __i) { return String(__v("seq")); } }, { childId: "__rc1", fn: function (__v, __i) { return String(__v("payDd")); } }, { childId: "__rc2", fn: function (__v, __i) { return String(__v("lstPayAmt")); } }, { childId: "__rc3", fn: function (__v, __i) { return String(__v("lstFeeAnulfeeTpCdnm")); } }] }];
    let gf = __genFills;
    for (let g = 0; g < gf.length; g++) {
        let f = gf[g];
        let gen = $c.util.getComponent(f.genId);
        let ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { continue; }
        let n = ds.getTotalRow();
        if (!n) { continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        if (gen.getLength && gen.getLength() > 0) { continue; }
        let __row = 0;
        let __cell = function (col) { let v = ds.getCellData(__row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            __row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                let ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(__cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                let cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
        }
    }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "__rb0", fn: function () { return "전체 " + String($c.data.readValue("dma_page", "total", { silent: true })) + "건 (" + String($c.data.readValue("dma_page", "currentPage", { silent: true })) + "/" + String($c.data.readValue("dma_page", "endListPage", { silent: true })) + " 페이지) "; } }];
    $c.data.copyRows(__rowCopies);
};

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_goPrintReq').set('pageIndex', "1");
};


// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.sub_printDate_Y = undefined; scwin.sub_printDate_M = undefined; scwin.sub_printDate_D = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35706.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.cal_startDate_onblur
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.cal_startDate_onblur = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; $c.cm.fn_CheckDate(__self); 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35706.cal_startDate_onblur' }); }
};

/**
 * @event
 * @name scwin.cal_endDate_onblur
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.cal_endDate_onblur = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; $c.cm.fn_CheckDate(__self); 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35706.cal_endDate_onblur' }); }
};

/**
 * @event
 * @name scwin.rd_period_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.rd_period_onclick = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; scwin.changePeriod('7D',__self) 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35706.rd_period_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_searchList_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchList_onclick = async function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; await scwin.fn_searchList() 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35706.btn_searchList_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_pageSize_onchange
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_pageSize_onchange = async function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; scwin.initPageIndex();await scwin.fn_searchList() 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35706.slc_pageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_printReceipt_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_printReceipt_onclick = async function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; await scwin.fn_printReceipt() 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35706.btn_printReceipt_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_goPrint
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_goTab2
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goTab2 = async function () {
    const sbmOptions = {
        id: "tx_fn_goTab2",
        method: "post",
        action: "listFee.do",
        ref: "dma_goTab2Req",
        target: "dlt_result=body",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil35706.tx_fn_goTab2" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fn_searchList
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_searchList = async function () {
    let frm = (document.listFeeReceiptForm || { elements: [] });
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_goPrintReq').set('method', "searchListFeeReceipt");
    frm.submit();
};


/**
 * @method
 * @name scwin.fn_printReceipt
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_printReceipt = async function () {
    let frm = (document.listFeeReceiptForm || { elements: [] });
    let cnt = 0;
    let seq = 0;
    let isurCd = "";
    let rcvDd = "";
    if (($c.util.getComponent('dlt_result').getTotalRow() > 0)) {
        if ($c.util.getComponent('dlt_result').getTotalRow()) {
            for (let i = 0; i < $c.util.getComponent('dlt_result').getTotalRow(); i++) {
                if ((['true', 'Y', '1'].indexOf(String($c.util.getComponent('dlt_result').getCellData(i, 'seq'))) >= 0)) {
                    cnt = cnt + 1;
                    seq = $c.util.getComponent('dlt_result').getCellData(i, 'seq');
                    isurCd = $c.util.getComponent('dlt_result').getCellData(i, 'isurCd');
                    rcvDd = $c.util.getComponent('dlt_result').getCellData(i, 'rcvDd');
                }
            }
        } else {
            if (($c.util.getComponent('dlt_result').getTotalRow() > 0).checked) {
                cnt = cnt + 1;
                seq = $c.util.getComponent('dlt_result').getCellData(0, 'seq');
                isurCd = $c.util.getComponent('dma_goPrintReq').get('isurCd');
                rcvDd = $c.util.getComponent('dma_goPrintReq').get('rcvDd');
            }
        }
    }
    if (cnt === 1) {
        scwin.fn_goPrint(seq, isurCd, rcvDd);
    } else {
        await $c.win.alert("영수증발급 대상을 1개 체크후 인쇄를 누르세요.");
        return;
    }
};


/**
 * @method
 * @name scwin.fn_goPrint
 * @author Inswave
 * @date 2026. 09. 06
 * @param seq isurCd rcvDd
 * @returns
 * @hidden N
*/
scwin.fn_goPrint = function (seq, isurCd, rcvDd) {
    let rexName = "RLDFIL00030";
    let dataLocation = "/outer/reportPrint.do?ipt_method_2=searchListFeeNewReport&isurCd=" + isurCd + "&rcvDd=" + rcvDd + "&seq=" + seq;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                let result = $.parseJSON(data);
                let form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_goPrintReq').set('ncomNm', result.comNm);
                $c.util.getComponent('dma_goPrintReq').set('npayDd', result.payDd);
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt', result.lstPayAmt);
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt1', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt2', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt3', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt4', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt5', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt6', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt7', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt8', '');
                $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt9', '');
                if (typeof result.lstPayAmt1 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt1', result.lstPayAmt1);
                }
                if (typeof result.lstPayAmt2 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt2', result.lstPayAmt2);
                }
                if (typeof result.lstPayAmt3 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt3', result.lstPayAmt3);
                }
                if (typeof result.lstPayAmt4 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt4', result.lstPayAmt4);
                }
                if (typeof result.lstPayAmt5 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt5', result.lstPayAmt5);
                }
                if (typeof result.lstPayAmt6 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt6', result.lstPayAmt6);
                }
                if (typeof result.lstPayAmt7 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt7', result.lstPayAmt7);
                }
                if (typeof result.lstPayAmt8 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt8', result.lstPayAmt8);
                }
                if (typeof result.lstPayAmt9 !== 'undefined') {
                    $c.util.getComponent('dma_goPrintReq').set('nlstPayAmt9', result.lstPayAmt9);
                }
                $c.util.getComponent('dma_goPrintReq').set('nlstFeeAnulfeeTpCdnm', result.lstFeeAnulfeeTpCdnm);
                $c.util.getComponent('dma_goPrintReq').set('nTempleteCd', rexName);
                if (result.today) {
                    let sub_printDate = result.today;
                    scwin.sub_printDate_Y = sub_printDate.substring(0, 4);
                    scwin.sub_printDate_M = sub_printDate.substring(4, 6);
                    scwin.sub_printDate_D = sub_printDate.substring(6, 8);
                    $c.util.getComponent('dma_goPrintReq').set('ntoDay', scwin.sub_printDate_Y + "." + scwin.sub_printDate_M + "." + scwin.sub_printDate_D);
                } else {
                    $c.util.getComponent('dma_goPrintReq').set('ntoDay', result.today);
                }
                await scwin.tx_fn_goPrint();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};


/**
 * @method
 * @name scwin.changePeriod
 * @author Inswave
 * @date 2026. 09. 06
 * @param type obj
 * @returns
 * @hidden N
*/
scwin.changePeriod = function (type, obj) {
    let startDate = ($c.util.getComponent('cal_startDate') || $c.util.getComponent('ipt_startDate') || $c.util.getComponent('startDate'));
    let endDate = ($c.util.getComponent('cal_endDate') || $c.util.getComponent('ipt_endDate') || $c.util.getComponent('endDate'));
    let ie = null;
    switch (type) {
        case '7D':
        scwin.fn_setDate(7, startDate, endDate, ie);
        break;
        case '1M':
        scwin.fn_setMonth(1, startDate, endDate, ie);
        break;
        case '1Y':
        scwin.fn_setFullYear(1, startDate, endDate, ie);
        break;
        case '2Y':
        scwin.fn_setFullYear(2, startDate, endDate, ie);
        break;
    }
};


/**
 * @method
 * @name scwin.fn_setDate
 * @author Inswave
 * @date 2026. 09. 06
 * @param pNewDd startDate endDate ie
 * @returns
 * @hidden N
*/
scwin.fn_setDate = function (pNewDd, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    vDate.setDate(vDate.getDate());
    vDate2.setDate(vDate.getDate() - pNewDd);
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};


/**
 * @method
 * @name scwin.fn_setMonth
 * @author Inswave
 * @date 2026. 09. 06
 * @param pNewmonth startDate endDate ie
 * @returns
 * @hidden N
*/
scwin.fn_setMonth = function (pNewmonth, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    vDate.setMonth(vDate.getMonth());
    vDate2.setMonth(vDate.getMonth() - pNewmonth);
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};


/**
 * @method
 * @name scwin.fn_setFullYear
 * @author Inswave
 * @date 2026. 09. 06
 * @param pNewyear startDate endDate ie
 * @returns
 * @hidden N
*/
scwin.fn_setFullYear = function (pNewyear, startDate, endDate, ie) {
    let vDate, vDate2, vMon2, vMon, vDay2, vDay;
    vDate = new Date();
    vDate2 = new Date();
    if (!ie) {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    } else {
        vDate.setFullYear(vDate.getFullYear());
        vDate2.setFullYear(vDate.getFullYear() - pNewyear);
    }
    if ((vDate2.getMonth() + 1) < 10) {
        vMon2 = "0" + String(vDate2.getMonth() + 1);
    } else {
        vMon2 = String(vDate2.getMonth() + 1);
    }
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate2.getDate() < 10) {
        vDay2 = "0" + String(vDate2.getDate());
    } else {
        vDay2 = String(vDate2.getDate());
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    $c.util.getComponent("cal_startDate").setValue(String(vDate2.getFullYear()) + String(vMon2) + String(vDay2));
    $c.util.getComponent("cal_endDate").setValue(String(vDate.getFullYear()) + String(vMon) + String(vDay));
};


/**
 * @method
 * @name scwin.fn_goTab1
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_goTab1 = function () {
    let frm = (document.listFeeReceiptForm || { elements: [] });
    frm.action = 'listFee.do';
    $c.util.getComponent('dma_goPrintReq').set('method', 'searchListFeeCalc');
    $c.win.moveUrl("/jldfil35700/jldfil35700.xml", { "method": 'searchListFeeCalc' });
};


/**
 * @method
 * @name scwin.fn_goTab2
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_goTab2 = async function () {
    let frm = (document.listFeeReceiptForm || { elements: [] });
    $c.util.getComponent('dma_goPrintReq').set('method', 'initListFeeReceipt');
    frm.action = 'listFee.do';
    await scwin.tx_fn_goTab2();
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_87_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param index
 * @returns
